def imperative_sum : List ℕ → ℕ :=
fun xs =>
  (have s := 0;
    do
    let r ←
      forIn xs s fun x r =>
          have s := r;
          have s := s + x;
          do
          pure PUnit.unit
          pure (ForInStep.yield s)
    have s : ℕ := r
    pure s).run

def imp_test : List ℤ → List ℤ :=
fun xs =>
  (have res := [];
    do
    let r ←
      forIn xs res fun x r =>
          have res := r;
          have res := res ++ [x];
          do
          pure PUnit.unit
          pure (ForInStep.yield res)
    have res : List ℤ := r
    pure res).run
